<button class="w-9 h-9 flex items-center justify-center rounded-xl bg-surface-container-low text-outline hover:text-on-surface hover:bg-surface-container transition-colors" type="button">
<span class="material-symbols-outlined text-[18px]">chevron_left</span>
</button>
<button class="w-9 h-9 flex items-center justify-center rounded-xl bg-primary-container text-on-primary-container font-label-md text-label-md font-bold shadow-sm" type="button">
          1
        </button>
<button class="w-9 h-9 flex items-center justify-center rounded-xl bg-surface-container-low text-on-surface font-label-md text-label-md hover:bg-surface-container transition-colors" type="button">
          2
        </button>
<button class="w-9 h-9 flex items-center justify-center rounded-xl bg-surface-container-low text-on-surface font-label-md text-label-md hover:bg-surface-container transition-colors" type="button">
          3
        </button>
<button class="w-9 h-9 flex items-center justify-center rounded-xl bg-surface-container-low text-outline hover:text-on-surface hover:bg-surface-container transition-colors" type="button">
<span class="material-symbols-outlined text-[18px]">chevron_right</span>
</button>
</div>
</div>
</div>
<!-- 5. Interactive Modal Form (Tambah / Edit Produk) -->
<div class="fixed inset-0 z-50 bg-inverse-surface/40 backdrop-blur-md flex items-center justify-center p-4 transition-opacity duration-300 opacity-0 pointer-events-none" id="productModalOverlay">
<div class="relative w-full max-w-3xl bg-surface-container-lowest rounded-3xl p-8 shadow-[0_25px_50px_-12px_rgba(91,77,255,0.25)] border border-white max-h-[90vh] overflow-y-auto transform transition-transform duration-300 scale-95" id="productModalContent">
<!-- Modal Header -->
<div class="flex items-start justify-between pb-6 border-b border-surface-container-high/60">
<div class="space-y-1">
<div class="inline-flex items-center gap-1.5 px-3 py-1 bg-primary-fixed text-on-primary-fixed-variant rounded-full font-label-badge text-label-badge font-bold">
<span class="material-symbols-outlined text-[14px]">tune</span> Formulir Katalog
          </div>
<h2 class="font-headline-lg text-headline-lg font-bold text-on-surface tracking-tight" id="modalTitle">Edit Rincian Produk / Bahan</h2>
<p class="font-body-md text-body-md text-on-surface-variant">
            Isi rincian informasi katalog inventaris Warkop Cak Kebo secara akurat.
          </p>
</div>
<button class="w-10 h-10 rounded-full bg-surface-container-low text-outline hover:text-on-surface hover:bg-surface-container flex items-center justify-center transition-colors" id="btnCloseModal" type="button">
<span class="material-symbols-outlined text-[20px]">close</span>
</button>
</div>
<!-- Modal Body (2-Column Grid Form) -->
<form class="mt-6 space-y-6" id="productForm" onsubmit="event.preventDefault();">
<div class="grid grid-cols-1 md:grid-cols-2 gap-5">
<!-- Field 1: Nama Produk -->
<div class="space-y-2">
<label class="block font-label-lg text-label-lg font-bold text-on-surface">Nama Produk / Bahan <span class="text-tertiary">*</span></label>
<input class="w-full px-4 py-3 bg-surface-container-low rounded-2xl text-on-surface font-body-sm text-body-sm focus:outline-none focus:ring-2 focus:ring-primary/20" placeholder="Contoh: Kopi Arabika Dampit Blend" required="" type="text" value="Kopi Arabika Dampit Blend">
</div>
<!-- Field 2: Kategori -->
<div class="space-y-2">
<label class="block font-label-lg text-label-lg font-bold text-on-surface">Kategori Produk <span class="text-tertiary">*</span></label>
<select class="w-full px-4 py-3 bg-surface-container-low rounded-2xl text-on-surface font-body-sm text-body-sm focus:outline-none focus:ring-2 focus:ring-primary/20 cursor-pointer">
<option selected="">Kopi &amp; Espresso</option>
<option>Susu &amp; Sirup</option>
<option>Bahan Kering &amp; Instan</option>
<option>Kemasan &amp; Cup</option>
<option>Makanan &amp; Snack</option>
</select>
</div>
<!-- Field 3: SKU / Barcode -->
<div class="space-y-2">
<label class="block font-label-lg text-label-lg font-bold text-on-surface">Kode SKU / Barcode</label>
<div class="relative">
<input class="w-full pl-4 pr-10 py-3 bg-surface-container-low rounded-2xl font-mono text-body-sm text-on-surface focus:outline-none focus:ring-2 focus:ring-primary/20" placeholder="WCK-KOP-008" type="text" value="WCK-KOP-008">
<span class="material-symbols-outlined absolute right-3 top-1/2 -translate-y-1/2 text-outline text-[18px]">barcode_scanner</span>
</div>
</div>
<!-- Field 4: Satuan Unit -->
<div class="space-y-2">
<label class="block font-label-lg text-label-lg font-bold text-on-surface">Satuan Unit Dasar</label>
<select class="w-full px-4 py-3 bg-surface-container-low rounded-2xl text-on-surface font-body-sm text-body-sm focus:outline-none focus:ring-2 focus:ring-primary/20 cursor-pointer">
<option selected="">Kilogram (kg)</option>
<option>Gram (g)</option>
<option>Kaleng</option>
<option>Pcs / Biji</option>
<option>Liter (L)</option>
<option>Porsi Menu</option>
</select>
</div>
<!-- Field 5: Harga Beli / HPP -->
<div class="space-y-2">
<label class="block font-label-lg text-label-lg font-bold text-on-surface">Harga Beli / HPP (Rp)</label>
<div class="relative">
<span class="absolute left-4 top-1/2 -translate-y-1/2 font-label-md text-label-md text-outline font-bold">Rp</span>
<input class="w-full pl-11 pr-4 py-3 bg-surface-container-low rounded-2xl font-body-sm text-body-sm text-on-surface focus:outline-none focus:ring-2 focus:ring-primary/20" placeholder="85.000" type="text" value="85.000">
</div>
</div>
<!-- Field 6: Harga Jual -->
<div class="space-y-2">
<label class="block font-label-lg text-label-lg font-bold text-on-surface">Harga Jual Pelanggan (Rp)</label>
<div class="relative">
<span class="absolute left-4 top-1/2 -translate-y-1/2 font-label-md text-label-md text-outline font-bold">Rp</span>
<input class="w-full pl-11 pr-4 py-3 bg-surface-container-low rounded-2xl font-body-sm text-body-sm text-on-surface focus:outline-none focus:ring-2 focus:ring-primary/20" placeholder="120.000" type="text" value="120.000">
</div>
</div>
<!-- Field 7: Stok Awal & Peringatan Minimum -->
<div class="space-y-2">
<label class="block font-label-lg text-label-lg font-bold text-on-surface">Stok Awal Saat Ini</label>
<input class="w-full px-4 py-3 bg-surface-container-low rounded-2xl font-body-sm text-body-sm text-on-surface focus:outline-none focus:ring-2 focus:ring-primary/20" step="0.1" type="number" value="5">
</div>
<div class="space-y-2">
<label class="block font-label-lg text-label-lg font-bold text-tertiary">Batas Stok Minimum Peringatan</label>
<input class="w-full px-4 py-3 bg-tertiary-fixed/20 rounded-2xl font-body-sm text-body-sm text-on-surface focus:outline-none focus:ring-2 focus:ring-tertiary/20" step="0.1" type="number" value="2">
</div>
<!-- Field 8: Catatan / Deskripsi Tambahan (Span 2 Cols) -->
<div class="md:col-span-2 space-y-2">
<label class="block font-label-lg text-label-lg font-bold text-on-surface">Catatan &amp; Lokasi Simpan</label>
<textarea class="w-full px-4 py-3 bg-surface-container-low rounded-2xl font-body-sm text-body-sm text-on-surface focus:outline-none focus:ring-2 focus:ring-primary/20" placeholder="Contoh: Penyimpanan di toples kedap udara rak atas bar..." rows="2">Penyimpanan di toples kedap udara rak atas bar racik utama.</textarea>
</div>
</div>
<!-- Switches / Toggles Section -->
<div class="p-4 bg-surface-container-low rounded-2xl flex flex-col sm:flex-row items-center justify-between gap-4">
<div class="flex items-center gap-3 w-full sm:w-auto">
<button class="w-12 h-6 bg-secondary rounded-full p-1 transition-colors duration-200 flex items-center justify-end" id="togglePos" type="button">
<div class="w-4 h-4 bg-white rounded-full shadow-sm"></div>
</button>
<div class="flex flex-col">
<span class="font-label-md text-label-md font-bold text-on-surface">Tampilkan di Kasir POS</span>
<span class="font-body-sm text-body-sm text-outline">Item muncul otomatis di tablet kasir</span>
</div>
</div>
<div class="h-px sm:h-8 w-full sm:w-px bg-surface-container-high"></div>
<div class="flex items-center gap-3 w-full sm:w-auto">
<button class="w-12 h-6 bg-secondary rounded-full p-1 transition-colors duration-200 flex items-center justify-end" id="toggleAlert" type="button">
<div class="w-4 h-4 bg-white rounded-full shadow-sm"></div>
</button>
<div class="flex flex-col">
<span class="font-label-md text-label-md font-bold text-on-surface">Pantau Stok Otomatis</span>
<span class="font-body-sm text-body-sm text-outline">Kirim notifikasi saat stok di bawah batas</span>
</div>
</div>
</div>
<!-- Modal Actions -->
<div class="flex items-center justify-end gap-3 pt-4 border-t border-surface-container-high/60">
<button class="px-5 py-2.5 rounded-2xl bg-surface-container-low text-on-surface font-label-lg text-label-lg hover:bg-surface-container transition-colors" id="btnCancelModal" type="button">
            Batal
          </button>
<button class="flex items-center gap-2 px-6 py-2.5 rounded-2xl bg-gradient-to-r from-secondary to-primary-container text-on-primary font-label-lg text-label-lg font-bold shadow-[0_10px_20px_-4px_rgba(0,108,73,0.35)] hover:shadow-[0_14px_24px_-4px_rgba(0,108,73,0.45)] hover:-translate-y-0.5 active:translate-y-0 transition-all" id="btnSaveModal" type="button">
<span class="material-symbols-outlined text-[20px]">save</span>
<span class="">Simpan Produk &amp; Sinkronisasi</span>
</button>
</div>
</form>
</div>
</div>
</div>
<!-- Interactive Client-side Script -->
<script>
  (function() {
    const modalOverlay = document.getElementById('productModalOverlay');
    const modalContent = document.getElementById('productModalContent');
    const btnOpenAdd = document.getElementById('btnOpenAddModal');
    const btnClose = document.getElementById('btnCloseModal');
    const btnCancel = document.getElementById('btnCancelModal');
    const btnSave = document.getElementById('btnSaveModal');
    const modalTitle = document.getElementById('modalTitle');
    const editButtons = document.querySelectorAll('.btn-edit-row');
    const categoryChips = document.querySelectorAll('.category-chip');
    const togglePos = document.getElementById('togglePos');
    const toggleAlert = document.getElementById('toggleAlert');

    function openModal(titleText) {
      if (titleText) modalTitle.innerText = titleText;
      modalOverlay.classList.remove('opacity-0', 'pointer-events-none');
      modalContent.classList.remove('scale-95');
      modalContent.classList.add('scale-100');
    }

    function closeModal() {
      modalOverlay.classList.add('opacity-0', 'pointer-events-none');
      modalContent.classList.remove('scale-100');
      modalContent.classList.add('scale-95');
    }

    if (btnOpenAdd) {
      btnOpenAdd.addEventListener('click', () => {
        openModal('Tambah Produk Baru');
      });
    }

    if (btnClose) btnClose.addEventListener('click', closeModal);
    if (btnCancel) btnCancel.addEventListener('click', closeModal);

    if (btnSave) {
      btnSave.addEventListener('click', () => {
        btnSave.innerHTML = '<span class="material-symbols-outlined text-[20px] animate-spin">refresh</span> Menyimpan...';
        setTimeout(() => {
          btnSave.innerHTML = '<span class="material-symbols-outlined text-[20px]">check_circle</span> Tersimpan!';
          setTimeout(() => {
            closeModal();
            btnSave.innerHTML = '<span class="material-symbols-outlined text-[20px]">save</span> <span>Simpan Produk & Sinkronisasi</span>';
          }, 600);
        }, 800);
      });
    }

    // Modal Edit buttons
    editButtons.forEach((btn) => {
      btn.addEventListener('click', () => {
        openModal('Edit Rincian Produk / Bahan');
      });
    });

    // Close on overlay backdrop tap
    if (modalOverlay) {
      modalOverlay.addEventListener('click', (e) => {
        if (e.target === modalOverlay) closeModal();
      });
    }

    // Category Filter Pills Toggle
    categoryChips.forEach((chip) => {
      chip.addEventListener('click', () => {
        categoryChips.forEach((c) => {
          c.classList.remove('bg-gradient-to-r', 'from-secondary', 'to-primary-container', 'text-on-primary', 'shadow-[0_6px_14px_-3px_rgba(0,108,73,0.35)]');
          c.classList.add('text-on-surface-variant', 'bg-surface-container-low');
        });
        chip.classList.add('bg-gradient-to-r', 'from-secondary', 'to-primary-container', 'text-on-primary', 'shadow-[0_6px_14px_-3px_rgba(0,108,73,0.35)]');
        chip.classList.remove('text-on-surface-variant', 'bg-surface-container-low');
      });
    });

    // Interactive Toggle Switch simulation
    function handleToggle(toggleElement) {
      if (!toggleElement) return;
      toggleElement.addEventListener('click', () => {
        const isRight = toggleElement.classList.contains('justify-end');
        if (isRight) {
          toggleElement.classList.remove('justify-end', 'bg-secondary');
          toggleElement.classList.add('justify-start', 'bg-outline/30');
        } else {
          toggleElement.classList.remove('justify-start', 'bg-outline/30');
          toggleElement.classList.add('justify-end', 'bg-secondary');
        }
      });
    }

    handleToggle(togglePos);
    handleToggle(toggleAlert);

    // Live search simulation
    const searchInput = document.getElementById('searchInput');
    const rows = document.querySelectorAll('#productRowsList > div');
    if (searchInput) {
      searchInput.addEventListener('input', (e) => {
        const query = e.target.value.toLowerCase().trim();
        rows.forEach((row) => {
          const text = row.innerText.toLowerCase();
          if (text.includes(query)) {
            row.style.display = 'grid';
          } else {
            row.style.display = 'none';
          }
        });
      });
    }
  })();
</script></main></div>

</body></html>
